{
  "findings": [
    {
      "check_id": "CKV_AZURE_229",
      "title": "Azure SQL Database is not zone redundant",
      "resource": "azurerm_mssql_database.main",
      "severity": "MEDIUM",
      "explanation": "The database does not enable zone redundancy, leaving it more susceptible to an availability-zone failure. Its existing S0 SKU does not support zone redundancy."
    }
  ],
  "patched_code": "resource \"azurerm_mssql_database\" \"main\" {\n  name           = \"${var.project_name}-database\"\n  server_id      = azurerm_mssql_server.main.id\n  collation      = \"SQL_Latin1_General_CP1_CI_AS\"\n  license_type   = \"LicenseIncluded\"\n  max_size_gb    = 20\n  sku_name       = \"P1\"\n  zone_redundant = true\n  tags           = var.common_tags\n}\n",
  "fix_summary": "Enabled zone redundancy for the Azure SQL database and changed the SKU from S0 to the zone-redundancy-capable P1 tier."
}
